ee:message.ee:set-payload:
%dw 2.0
output application/json
import util::GlobalFunctions as global
import * from dw::util::Values
import partition, indexOf from dw::core::Arrays

var fechaInicioFacturacion = global::formatDate(vars.inputBody.respuestaAprovisionamiento.fechaInicioFacturacion) default null

fun updateProducts(prod, index) = do {
  var categorized = (prod.parametros partition ($.codigo == "ATT_SF_Nemonico"))
  ---
  prod update "parametros" with
  //No parameter with code "ATT_SF_Nemonico" returns same array
  (if (sizeOf(categorized.success) == 0) prod.parametros
  //else it updates every attribute (should be only 1) and returns modified array
  else categorized.failure ++ (categorized.success map $ update "valor" with vars.itemsToBeUpdated[index].idServicio))
}

fun updateItems() = vars.responseOrderById.items map ((item, index) -> do {
    var indxItem = indexOf(vars.itemsToBeUpdated, (vars.itemsToBeUpdated filter ($.idItem == item.idItem))[0])
	---
	if (indxItem != -1) 
	  if (item.fechaInicioFacturacion == null) 
	    (item update "productos" with updateProducts(item.productos, indxItem)) ++ {"fechaInicioFacturacion": fechaInicioFacturacion}
	  else 
	    (item update "productos" with updateProducts(item.productos, indxItem)) update "fechaInicioFacturacion" with fechaInicioFacturacion
	else
	  if(item.fechaInicioFacturacion == null)
    	(item ++ {"fechaInicioFacturacion": fechaInicioFacturacion})
  else
    item update "fechaInicioFacturacion" with fechaInicioFacturacion
})

---
vars.responseOrderById update "items" with updateItems()

%dw 2.0
output application/json
import util::GlobalFunctions as global
import * from dw::util::Values
---
if (vars.orderState == "OR0020"){
			"estadoOrden": {
			"fecha": now(),
			"codigoEstado": "OR0020",
			"nombreEstado": "EN_PROCESO",
			"observaciones": "EN_PROCESO"
			}
		}
else if (vars.orderState == "OR0021") {
			"estadoOrden": {
			"fecha": now(),
			"codigoEstado": "OR0021",
			"nombreEstado": "ERROR_VALIDACION",
			"observaciones": "ERROR_VALIDACION"
			}
		}
else if (vars.orderState == "OR0060") global::updateOrderState( (payload update "items" with  global::updateItemsState(payload,vars.itemsToBeUpdated.idItem,"ITM30","RESPUESTA_BACK_PROCESADA")),"OR0020","EN_PROCESO")
else null
